namespace sv_3022a7d4496d44e1863cd0b0a4e6d35b.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped (per-circuit) service that holds theme state and notifies subscribers on change.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Mode or AccentColor changes.
    /// Components subscribe to this and call StateHasChanged.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Apply multiple changes atomically (fires OnChange only once).
    /// </summary>
    public void Update(ThemeMode mode, string accentColor)
    {
        bool changed = _mode != mode || _accentColor != accentColor;
        _mode = mode;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

// Applies theme attributes to <html> so CSS can target [data-theme="dark"] etc.
export function applyTheme(mode, accentColor) {
    const html = document.documentElement;

    let resolved = mode.toLowerCase();
    if (resolved === "system") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark"
            : "light";
    }

    html.setAttribute("data-bs-theme", resolved);   // Bootstrap 5.3+ dark mode
    html.setAttribute("data-theme", resolved);       // custom CSS hook
    html.style.setProperty("--accent-color", accentColor);
}

@* Interactive island that lives in the static layout header *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme
@inject IJSRuntime JS

<span class="theme-indicator" title="Current theme">
    @GetIcon() @Theme.Mode
    <span class="accent-dot" style="background-color: @Theme.AccentColor;"></span>
</span>

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme-interop.js");
            Theme.OnChange += HandleThemeChanged;
        }

        // Always push current theme to the DOM after render
        if (_module is not null)
        {
            await _module.InvokeVoidAsync(
                "applyTheme", Theme.Mode.ToString(), Theme.AccentColor);
        }
    }

    private void HandleThemeChanged() =>
        InvokeAsync(StateHasChanged);

    private string GetIcon() => Theme.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    public void Dispose() => Theme.OnChange -= HandleThemeChanged;
}

@* Drop-in interactive toggle — usable in sidebar, toolbar, or any page *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<div class="theme-toggle">
    <button class="btn btn-sm @ButtonClass" @onclick="CycleTheme"
            title="Switch theme">
        @GetIcon() @Theme.Mode
    </button>
</div>

@code {
    protected override void OnInitialized() =>
        Theme.OnChange += HandleThemeChanged;

    private void CycleTheme()
    {
        Theme.Mode = Theme.Mode switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
