// Applies theme attributes to <html> so CSS can target [data-theme="dark"] etc.
export function applyTheme(mode, accentColor) {
    const html = document.documentElement;

    let resolved = mode.toLowerCase();
    if (resolved === "system") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark"
            : "light";
    }

    html.setAttribute("data-bs-theme", resolved);   // Bootstrap 5.3+ dark mode
    html.setAttribute("data-theme", resolved);       // custom CSS hook
    html.style.setProperty("--accent-color", accentColor);
}

